124	  BaseLayer(LottieDrawable lottieDrawable, Layer layerModel) {
125	    this.lottieDrawable = lottieDrawable;
126	    this.layerModel = layerModel;
127	    drawTraceName = layerModel.getName() + "#draw";
128	    if (layerModel.getMatteType() == Layer.MatteType.INVERT) {
129	      mattePaint.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.DST_OUT));
130	    } else {
131	      mattePaint.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.DST_IN));
132	    }
133	
134	    this.transform = layerModel.getTransform().createAnimation();
135	    transform.addListener(this);
136	
137	    if (layerModel.getMasks() != null && !layerModel.getMasks().isEmpty()) {
138	      this.mask = new MaskKeyframeAnimation(layerModel.getMasks());
139	      for (BaseKeyframeAnimation<?, Path> animation : mask.getMaskAnimations()) {
140	        // Don't call addAnimation() because progress gets set manually in setProgress to
141	        // properly handle time scale.
142	        animation.addUpdateListener(this);
143	      }
144	      for (BaseKeyframeAnimation<Integer, Integer> animation : mask.getOpacityAnimations()) {
145	        addAnimation(animation);
146	        animation.addUpdateListener(this);
147	      }
148	    }
149	    setupInOutAnimations();
150	  }
