152	  /**
153	   * Enable this to debug slow animations by outlining masks and mattes. The performance overhead of the masks and mattes will
154	   * be proportional to the surface area of all of the masks/mattes combined.
155	   * <p>
156	   * DO NOT leave this enabled in production.
157	   */
158	  void setOutlineMasksAndMattes(boolean outline) {
159	    if (outline && outlineMasksAndMattesPaint == null) {
160	      outlineMasksAndMattesPaint = new LPaint();
