213	  @CallSuper
214	  @Override
215	  public void getBounds(
216	      RectF outBounds, Matrix parentMatrix, boolean applyParents) {
217	    rect.set(0, 0, 0, 0);
218	    buildParentLayerListIfNeeded();
219	    boundsMatrix.set(parentMatrix);
220	
221	    if (applyParents) {
222	      if (parentLayers != null) {
223	        for (int i = parentLayers.size() - 1; i >= 0; i--) {
224	          boundsMatrix.preConcat(parentLayers.get(i).transform.getMatrix());
225	        }
226	      } else if (parentLayer != null) {
227	        boundsMatrix.preConcat(parentLayer.transform.getMatrix());
228	      }
229	    }
230	
231	    boundsMatrix.preConcat(transform.getMatrix());
232	  }
