234	  @Override
235	  public void draw(Canvas canvas, Matrix parentMatrix, int parentAlpha, @Nullable DropShadow shadowToApply) {
236	    L.beginSection(drawTraceName);
237	    if (!visible || layerModel.isHidden()) {
238	      L.endSection(drawTraceName);
239	      return;
240	    }
241	    buildParentLayerListIfNeeded();
242	    if (L.isTraceEnabled()) {
243	      L.beginSection("Layer#parentMatrix");
244	    }
245	    matrix.reset();
246	    matrix.set(parentMatrix);
247	    for (int i = parentLayers.size() - 1; i >= 0; i--) {
248	      matrix.preConcat(parentLayers.get(i).transform.getMatrix());
249	    }
250	    if (L.isTraceEnabled()) {
251	      L.endSection("Layer#parentMatrix");
252	    }
253	    // It is unclear why but getting the opacity here would sometimes NPE.
254	    // The extra code here is designed to avoid this.
255	    // https://github.com/airbnb/lottie-android/issues/2083
256	    int opacity = 100;
257	    BaseKeyframeAnimation<?, Integer> opacityAnimation = transform.getOpacity();
258	    if (opacityAnimation != null) {
259	      Integer opacityValue = opacityAnimation.getValue();
260	      if (opacityValue != null) {
261	        opacity = opacityValue;
262	      }
263	    }
264	    int alpha = (int) ((parentAlpha / 255f * (float) opacity / 100f) * 255);
265	    if (!hasMatteOnThisLayer() && !hasMasksOnThisLayer() && getBlendMode() == LBlendMode.NORMAL) {
266	      matrix.preConcat(transform.getMatrix());
267	      if (L.isTraceEnabled()) {
268	        L.beginSection("Layer#drawLayer");
269	      }
270	      drawLayer(canvas, matrix, alpha, shadowToApply);
271	      if (L.isTraceEnabled()) {
272	        L.endSection("Layer#drawLayer");
273	      }
274	      recordRenderTime(L.endSection(drawTraceName));
275	      return;
276	    }
277	
278	    if (L.isTraceEnabled()) {
279	      L.beginSection("Layer#computeBounds");
280	    }
281	    getBounds(rect, matrix, false);
282	
283	    intersectBoundsWithMatte(rect, parentMatrix);
